body.script:
const canvas = document.getElementById('eyeCanvas');
const ctx = canvas.getContext('2d');

let angle = 0;

// Định nghĩa đường viền hốc mắt trái (khung mở)
function drawLeftEyeContour() {
  ctx.beginPath();
  ctx.moveTo(460, 370); // Khóe trong
  ctx.bezierCurveTo(360, 220, 220, 230, 80, 250); // Mí trên
  ctx.bezierCurveTo(170, 390, 320, 420, 460, 370); // Mí dưới
  ctx.closePath();
}

// Định nghĩa đường viền hốc mắt phải
function drawRightEyeContour() {
  ctx.beginPath();
  ctx.moveTo(540, 370); // Khóe trong
  ctx.bezierCurveTo(640, 220, 780, 230, 920, 250); // Mí trên
  ctx.bezierCurveTo(830, 390, 680, 420, 540, 370); // Mí dưới
  ctx.closePath();
}

// Vẽ xoáy lốc ma thuật
function drawVortex(cx, cy, rotationDir) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(angle * rotationDir);

  // Quầng sáng nền bên trong con ngươi
  const bgGrad = ctx.createRadialGradient(0, 0, 10, 0, 0, 150);
  bgGrad.addColorStop(0, '#ffffff');
  bgGrad.addColorStop(0.2, '#38bdf8');
  bgGrad.addColorStop(0.5, '#1d4ed8');
  bgGrad.addColorStop(0.8, '#090d2e');
  bgGrad.addColorStop(1, '#010206');
  ctx.fillStyle = bgGrad;
  ctx.beginPath();
  ctx.arc(0, 0, 160, 0, Math.PI * 2);
  ctx.fill();

  // Các nhánh xoắn ốc phát sáng
  for (let i = 0; i < 4; i++) {
    ctx.save();
    ctx.rotate((i * Math.PI) / 2);
    ctx.beginPath();
    ctx.lineWidth = 14 - i * 2;
    ctx.strokeStyle = i % 2 === 0 ? '#93c5fd' : '#3b82f6';
    ctx.shadowColor = '#00a6ff';
    ctx.shadowBlur = 18;

    for (let t = 0; t < 25; t++) {
      const r = t * 6;
      const a = t * 0.28;
      const x = r * Math.cos(a);
      const y = r * Math.sin(a);
      if (t === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  // Lõi tâm màu trắng rực
  ctx.beginPath();
  ctx.arc(0, 0, 18, 0, Math.PI * 2);
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = '#60a5fa';
  ctx.shadowBlur = 25;
  ctx.fill();

  ctx.restore();
}

// Các mảnh gai bóng tối cắt qua mắt tạo độ hung dữ
function drawShadowShards() {
  ctx.fillStyle = '#010206';
  ctx.shadowBlur = 0;

  // Gai mí mắt trái
  ctx.beginPath();
  ctx.moveTo(250, 200); ctx.lineTo(280, 270); ctx.lineTo(310, 210);
  ctx.lineTo(360, 290); ctx.lineTo(390, 230); ctx.lineTo(440, 320);
  ctx.lineTo(460, 200);
  ctx.fill();

  // Gai mí mắt phải
  ctx.beginPath();
  ctx.moveTo(750, 200); ctx.lineTo(720, 270); ctx.lineTo(690, 210);
  ctx.lineTo(640, 290); ctx.lineTo(610, 230); ctx.lineTo(560, 320);
  ctx.lineTo(540, 200);
  ctx.fill();

  // Khối bóng nhọn giữa sống mũi
  ctx.beginPath();
  ctx.moveTo(500, 150);
  ctx.lineTo(470, 330);
  ctx.lineTo(500, 420);
  ctx.lineTo(530, 330);
  ctx.closePath();
  ctx.fill();
}

// Vòng lặp dựng hình liên tục
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // 1. Dựng mắt trái
  ctx.save();
  drawLeftEyeContour();
  ctx.clip();
  drawVortex(275, 310, 1);
  ctx.restore();

  // 2. Dựng mắt phải
  ctx.save();
  drawRightEyeContour();
  ctx.clip();
  drawVortex(725, 310, -1);
  ctx.restore();

  // 3. Phủ mảng bóng tối và chi tiết góc cạnh
  drawShadowShards();

  angle += 0.025; // Điều chỉnh tốc độ xoay
  requestAnimationFrame(render);
}

render();
